interface LogTrace {
  details?: Record<string, unknown>;
  logType: string;
  operationName: string;
  runtime: number;
  srcLocation: string;
}

/**
 * Execution function and log runtime
 * @param logger Application logger
 * @param context Job Log Context
 * @param operation Function to execute
 * @param operationInfo Function properties
 * @param operationInfo.name Function name
 * @param operationInfo.srcLocation Caller code source location
 * @param details (optional)
 * @param startTime starting time
 * @returns function output
 */
export async function execAndLog<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  operationInfo: {
    name: string;
    srcLocation: string;
  },
  details?: Record<string, unknown>,
  startTime = Date.now(),
): Promise<T> {
  const result = await operation();
  const logTrace: LogTrace = {
    details,
    logType: 'Exec trace',
    operationName: operationInfo.name,
    runtime: Date.now() - startTime,
    srcLocation: operationInfo.srcLocation,
  };
  logger.debug(JSON.stringify(logTrace), context);
  return result;
}

