import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class TelemetryConfigService implements OnModuleInit {
  private readonly context: JobsLogContext = {
    method: '',
    service: TelemetryConfigService.name,
  };

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get enableTelemetry(): boolean {
    return this.configService.get<string>('enableTelemetry') === 'true';
  }

  public get enableRedisInstrumentation(): boolean {
    return (
      this.configService.get<string>('enableRedisInstrumentation') === 'true'
    );
  }

  public get enableMetrics(): boolean {
    return this.configService.get<string>('enableMetrics') === 'true';
  }

  public get enableLiveMetrics(): boolean {
    return this.configService.get<string>('enableLiveMetrics') === 'true';
  }

  public get enablePerformanceCounters(): boolean {
    return (
      this.configService.get<string>('enablePerformanceCounters') === 'true'
    );
  }

  public get connectionString(): string | undefined {
    return this.configService.get<string>(
      'applicationInsightsConnectionString',
    );
  }

  public get serviceName(): string {
    return this.configService.get<string>('serviceName') ?? '';
  }

  public get samplingRatio(): number | undefined {
    const value = this.configService.get<string>('telemetrySamplingRatio');
    return value === undefined ? undefined : Number(value);
  }

  public get hostName(): string | undefined {
    return this.configService.get<string>('hostname') ?? os.hostname();
  }

  public async onModuleInit(): Promise<void> {
    await this.validateConfiguration();
  }

  /* =======================
   * Validation (read-only, no initialization)
   * ======================= */

  private async validateConfiguration(): Promise<void> {
    this.context.method = 'validateConfiguration';

    if (!(await this.appConfigService.reachable())) {
      const message = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;
      this.customLogger.error(message, this.context);
      throw new Error(message);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      {
        key: 'enableTelemetry',
        value: this.enableTelemetry,
      },
      {
        key: 'enableRedisInstrumentation',
        value: this.enableRedisInstrumentation,
      },
      {
        key: 'applicationInsightsConnectionString',
        value: this.enableTelemetry ? this.connectionString : true, // Skip when telemetry disabled
      },
      {
        key: 'serviceName',
        value: this.serviceName,
      },
      {
        key: 'samplingRatio',
        value: this.samplingRatio,
      },
      {
        key: 'hostName',
        value: this.hostName,
      },
    ];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.log(
      'All required Telemetry configurations are properly set',
      this.context,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';

import { EventEmitter2 } from '@nestjs/event-emitter';

import { DaprClient } from 'dapr-client';

import { AggregatorService } from '@/common/aggregator/aggregator.service';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MappingService } from '@/common/mapping/service/mapping.service';

import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';

import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';
import { getListPlant } from '@/helpers/caches/get-plant-list';
import { emitSqlEvent } from '@/helpers/events/emit-sql-events';
import {
  decrementPendingMessageCount,
  incrementPendingMessageCount,
} from '@/helpers/statistics/pending-message-stats';
import { validateAndTrackChanges } from '@/helpers/validations/validate-and-track-data-changes';
import { IngestionEventTrackingService } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.service';

@Injectable()
export class DaprServiceApi implements OnModuleInit {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprServiceApi.name, userId };
  }

  private plantList: Array<PlantsResponseDto> = [];

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly mappingService: MappingService,
    private readonly eventEmitter: EventEmitter2,
    private readonly redisConfigService: RedisConfigService,
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly aggregatorService: AggregatorService,
  ) {
    this.daprClient = new DaprClient();
  }

  public getDaprClient(): DaprClient {
    return this.daprClient;
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
  }

  public async initializePlant(): Promise<void> {
    const context = DaprServiceApi.createLogContext('initializePlant');
    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStore,
        this.redisConfigService.redisPlantKey,
      );
      this.customLogger.log(
        `Updated Plants List: ${JSON.stringify(this.plantList)}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error,
      );
    }
  }

  /**
   * Process the message
   * @param message Mapped Data to process
   * @param redisStore redisStore
   */
  private async processMessage(
    message: RedisMessage,
    redisStore: string,
  ): Promise<void> {
    const {
      mappedData,
      destination,
      operation,
      keysValueArray,
      cacheTreatment,
      ingestionEventTracking,
    } = message;
    const plant = mappedData?.plant;
    const context = DaprServiceApi.createLogContext(
      'processMessage',
      mappedData?.plant,
    );
    try {
      if (!operation || !keysValueArray) {
        return;
      }
      if (operation !== 'r' && ingestionEventTracking) {
        const validateAndTrackIngestionEventTracking: boolean =
          await validateAndTrackChanges(
            this.customLogger,
            this.ingestionEventTrackingService,
            ingestionEventTracking,
          );
        if (!validateAndTrackIngestionEventTracking) {
          return;
        }
        await this.ingestionEventTrackingService.upsertCache(
          ingestionEventTracking,
        );
      }
      await (cacheTreatment
        ? this.aggregatorService.processWithAggregation(
            plant,
            message,
            keysValueArray,
            redisStore,
          )
        : emitSqlEvent(
            this.customLogger,
            context,
            this.eventEmitter,
            destination,
            mappedData,
            operation,
          ));
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record Record To handle
   */
  public async handleMessage(record: CombinedDtoWithIndex): Promise<void> {
    const context = DaprServiceApi.createLogContext('handleMessage');
    this.customLogger.debug(
      `Received - payload: ${JSON.stringify(record)}`,
      context,
    );
    incrementPendingMessageCount();
    const dateStart = Date.now();
    const shopOrder = record.SHOP_ORDER ?? record.S_SHOP_ORDER ?? 'unknown';
    const operationInfo = {
      name: '',
      srcLocation: 'handleMessage',
    };
    const operationDetails = {
      shopOrder,
    };

    try {
      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.debug(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        context,
      );
      if (!sourceTable) return;
      const {
        mappedData,
        destination,
        ingestionEventTracking,
        keysValue,
        keysValueArray,
        cacheTreatment,
      } = this.mappingService.mapData(sourceTable, record, this.plantList);
      // Check first if there is two table source in the mapping system
      // Fifo check
      this.customLogger.debug(
        `Mapped Data:${JSON.stringify(mappedData)}`,
        context,
      );
      const newRecord = {
        cacheTreatment,
        destination,
        ingestionEventTracking,
        keysValue,
        keysValueArray,
        mappedData,
        operation,
        sourceTable,
      };
      await this.processMessage(newRecord, this.redisConfigService.redisStore);
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
    } finally {
      if (record) {
        operationInfo.name = 'handleMessage function runtime';
        await execAndLog(
          this.customLogger,
          context,
          async () => {},
          operationInfo,
          operationDetails,
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}
